// Corpus : arrêté du 25 juin 1980, livre II, TITRE II — dispositions
// particulières des types M (magasins), N (restaurants), O (hôtels) et W
// (bureaux). Lu le 2026-10-14.
//
// POURQUOI CE CORPUS EXISTE. Le titre II n'avait jamais été ouvert : la cible
// était N5 seule, et PE 1 § 1 écarte le livre II entier en 5ᵉ catégorie. Le
// 2026-10-12, la cible est devenue ce que l'onboarding ne refuse pas,
// catégories d'ERP 1 à 4 comprises (ADR-031). La propriétaire a lu les quatre
// chapitres des secteurs cibles le 2026-10-14 et décidé ce qui s'encode
// (points 1 à 6 de sa décision, voir `incendie.ts`) ; ce fichier consigne la
// lecture article par article, et le sort de chacun.
//
// COMMENT IL A ÉTÉ LU. Par l'API Légifrance (DILA, via PISTE,
// `src/lib/legifrance/client.ts`), environnement BAC À SABLE — son égalité
// avec la production n'est pas vérifiée. Table des matières du texte
// (`/consult/legi/tableMatieres`, LEGITEXT000020303557, à la date du
// 2026-10-14) pour la liste exhaustive des articles de chaque chapitre, puis
// chaque article par son LEGIARTI (`/consult/getArticle`). Les citations sont
// recopiées du texte de l'API, espaces normalisées ; l'intitulé que l'API colle
// en tête du texte en est retiré et porté par `intitule`. Une citation longue
// est coupée à une fin de phrase et marquée « […] ».
//
// CE QUE LA LECTURE N'A PAS FAIT. Les textes modificateurs (`modifiePar`) sont
// nommés tels que l'API les rend ; ils n'ont pas été ouverts en entier — ce que
// la règle de lecture de `types.ts` demande. Les articles qu'ils touchent dans
// ces quatre chapitres sont tous lus ici, dans leur version en vigueur ; ce
// qu'ils touchent ailleurs ne l'est pas. ~~Les dix autres chapitres du titre II
// (L, P, R, S, T, U, V, X, Y, J) ne sont pas ouverts.~~ [2026-10-16 : L est lu
// par la session du chantier multi-types (`propositions/lecture-chapitre-L-
// 2026-10-16.md`, hors de ce fichier tant qu'il n'est pas encodé) ; les neuf
// autres sont lus en entier et ajoutés ci-dessous — voir le bloc suivant.]
//
// LA LECTURE DU 2026-10-16 : P, R, S, T, U, V, X, Y, J. Même méthode, même
// environnement (API PISTE, BAC À SABLE, égalité avec la production non
// vérifiée) : table des matières de LEGITEXT000020303557 à la date du
// 2026-10-16, puis chaque article par son LEGIARTI. 295 entrées, la liste
// exhaustive de la table des matières, abrogés compris (quatorze) : P 24, R 33,
// S 19, T 54 (dont son annexe), U 62 (la table ne liste ni U 4 ni U 31), V 13,
// X 28 (dont son annexe), Y 22, J 40. Aucune version à venir. Les 174 articles
// du titre Ier auxquels ces chapitres renvoient ont été ouverts aussi ; ils ne
// sont pas ajoutés au corpus `arrete-1980-livre-2` (qui reste `articles_cites`),
// et ce qu'ils apportent est dit dans le plan de lecture
// (`propositions/lecture-chapitres-types-erp-2026-10-16.md`).
//
// RIEN N'EST ENCODÉ. Ce qu'un article impose et que le référentiel ne porte
// pas est `obligation_manquante`, avec sa proposition dans le motif :
// rattachement à une ligne existante quand c'est le même acte (personnel
// désigné, interdiction de fumer affichée, schéma d'organisation), sinon une
// ligne bornée N1–N4 et au type. Deux familles nouvelles de motifs communs :
// la manifestation temporaire du type T (ligne de partage 1) et le service
// d'agents de sécurité incendie (`non_couvert`, annoncé par l'axe
// `categorie_erp`). ~~Les piscines restent sous l'exclusion `risque_specialise`.~~
// [2026-10-17, revue indépendante : l'annexe du type X (traitement des eaux)
// et l'affichage de X 1 § 2 portent des actes de l'exploitant ; ils sont
// `obligation_manquante` à trancher avec X 25, X 3 et X 8 reclassés (condition,
// construction). Une exclusion dit qu'aucune obligation n'en découle.]
//
// LE CLASSEMENT, EN QUATRE FAMILLES — et le vocabulaire est celui du dépôt :
//  - `retenu` : les douze articles qui fondent une obligation (dont N 20, en
//    contexte de la consigne du Code du travail) ;
//  - `hors_perimetre` / `construction` : isolement, dégagements, désenfumage,
//    installations de chauffage, d'éclairage, de cuisson, classement des locaux
//    pour CO 27 — des règles qui s'adressent au constructeur ou à l'aménageur ;
//  - `sans_objet`, avec trois motifs communs ci-dessous : les généralités
//    (champ et calcul de l'effectif), les DOTATIONS (comme PE 24, PE 26, PE 32
//    au livre III), et les règles d'USAGE — interdictions, limites de
//    quantités, conditions d'emploi —, sans acte ni pièce ;
//  - un seul `hors_perimetre` / `risque_specialise` : M 40, dont le seul acte
//    est pris dans le régime des installations classées.

import type { Corpus } from "./types";

const MOTIF_GENERALITES =
  "Champ d'application ou calcul de l'effectif du chapitre : un seuil ou une règle de calcul, sans acte ni échéance. Ce sont ces seuils qui situent le chapitre dans les catégories 1 à 4 ; la catégorie, déclarée par l'exploitant, les porte, et les lignes du chapitre sont bornées par elle (`erp: { categories: [\"N1\", …, \"N4\"], types }`).";

const MOTIF_DOTATION =
  "Règle de DOTATION, sans récurrence : l'établissement doit être pourvu d'un moyen — extincteurs, robinets d'incendie armés, alarme, système de sécurité incendie, éclairage de sécurité, liaison avec les sapeurs-pompiers. Même classement que PE 24, PE 26 et PE 32 au livre III, pour la même raison : le produit ne modélise pas la conformité de l'installation, il suit les actes qu'elle appelle — les vérifications et l'entretien, portés par le référentiel et fondés sur le titre Ier (MS, EC, EL).";

const MOTIF_USAGE =
  "Règle d'USAGE ou d'aménagement — une interdiction, une limite de quantité ou de capacité, une condition d'emploi —, sans acte ni pièce : elle se respecte, elle ne se planifie pas, et une case cochée y ressemblerait à une preuve (ADR-027). Même famille que PE 34 au livre III. Aucune ne porte de rythme.";

const MOTIF_M40 =
  "Trois paragraphes. Les § 1 et § 2 sont des règles d'usage — vente des produits particulièrement inflammables réservée aux magasins spécialisés, emballages étanches, aucun transvasement —, de la famille des autres articles de la section 10, classés `sans_objet`. Le § 3 admet les solvants halogénés dans les ateliers de nettoyage à sec « sous réserve de respecter les prescriptions générales de la réglementation des installations classées pour la protection de l'environnement », et y ajoute cinq prescriptions, dont la seule qui soit un acte : « e) Souscrire un contrat d'entretien des machines de traitement suivant les instructions du constructeur ». ~~C'est une installation classée, que le produit déclare et ne couvre pas (`.claude/CLAUDE.md`, « ICPE ») ; l'exclusion `risque_specialise` est la plus proche — son libellé ne nomme que l'autorisation, et le régime de l'atelier n'a pas été lu. Classement à confirmer par la propriétaire.~~ [2026-10-15, décision de la propriétaire : « les conditions c'est pas nous, et les produits interdits non plus ». Les cinq prescriptions du § 3, contrat d'entretien compris, sont les conditions auxquelles le texte subordonne l'usage des solvants halogénés dans un atelier : les § 1, § 2 et § 3 a) à d) restent ici (règles d'usage, aménagement, produits interdits : aucun acte de l'exploitant à suivre) ; le seul acte, le contrat d'entretien du e), est classé à part et HORS CADRE — entrée « M 40 § 3 e) ». Un magasin qui abrite un pressing reste servi pour tout le reste de son dossier.]";

const MOTIF_O22 =
  "Section 11, établissements existants reclassés ERP : réputés conformes s'ils répondent à la réglementation de leur construction, et un RENVOI — les dispositions de contrôle (R. 123-51, GE 3, GE 4, GE 5, MS 74), d'entretien (DF 9, CH 57, GZ 14, EL 18, EC 13, AS 8, GC 21, MS 68, MS 72) et de vérification (GE 6 à GE 10, DF 10, CH 58, GZ 15, EL 19, EC 15, AS 9, GC 22, MS 71, MS 73) leur sont applicables. Il ne crée rien : ces articles valent déjà pour tout établissement des quatre premières catégories, et ceux que le référentiel porte le sont sans condition de date d'ouverture. Le renvoi à R. 123-51 du CCH est recopié tel que le texte l'écrit ; sa correspondance après la recodification du CCH n'est pas vérifiée ici.";

const MOTIF_O24 =
  "Section 11, établissements existants reclassés ERP : « Les dispositions des articles MS 45 à MS 48 sont applicables. » Un RENVOI au régime du service de sécurité incendie des dispositions générales, qui vaut déjà pour tout établissement du livre II ; il n'ajoute rien au chapitre, où O 18 (retenu) fait désigner et entraîner des employés. MS 45 à MS 48 n'ont pas été ouverts : ce que le renvoi apporte au-delà d'O 18 n'est pas établi ici.";

// ----- Ajoutés le 2026-10-16, avec les chapitres J, P, R, S, T, U, V, X, Y -----

const MOTIF_MANIFESTATION_T =
  "Type T : une obligation propre à une MANIFESTATION temporaire — foire, salon, exposition —, à la charge de l'organisateur, du chargé de sécurité ou de l'exposant, ou une condition de son autorisation (« L'organisateur doit demander à l'autorité administrative l'autorisation de tenir une activité du présent type deux mois avant son ouverture », T 5 § 1). Ligne de partage 1 : ce qui conditionne le droit de tenir la manifestation ne se rythme pas, et ce qui se fait pendant elle (déclarations à l'organisateur, stands, démonstrations) ne pèse pas sur l'établissement que Rojer suit. Une TPE exposante y est soumise sur le stand d'un autre ; son propre établissement reste servi pour tout le reste. La salle d'exposition permanente de T 1 § 2 n'a ni organisateur ni exposant.";

const MOTIF_SSIAP =
  "Service de sécurité incendie assuré par des AGENTS DE SÉCURITÉ INCENDIE (MS 46 § 1 b), ou composé d'un effectif fixé, au-delà d'un seuil de public ou en 1ʳᵉ catégorie. Comme M 29 § 2 à § 4 et L 14, Rojer ne le suit pas : un effectif présent n'est ni un acte daté ni une pièce, et le produit ne connaît pas l'effectif du public. Ce qui est suivi, c'est la désignation et l'entraînement d'employés là où le chapitre les prescrit. Annoncé par la phrase de manque de l'axe `categorie_erp`.";

const DECLARE_A_CATEGORIE_ERP =
  "src/lib/perimetre/couverture.ts — phrase de manque de l'axe `categorie_erp`, servie à tout ERP des catégories 1 à 4 : « le service de sécurité incendie assuré par des agents de sécurité incendie, notamment, n'y est pas, et des dispositions particulières par type d'activité, il ne porte que quelques-unes ».";

