      lecture: "api_legifrance",
      citationCle: "§ 1. Les dispositions particulières du présent chapitre sont applicables aux magasins, locaux ou aires de vente, centres commerciaux, etc., dans lesquels l'effectif du public est supérieur ou égal à l'un des chiffres suivants : – 100 personnes en sous-sol ou en étages, en galeries et autres ouvrages en surélévation ; – 200 personnes au total. § 2. Pour l'application des mesures contenues dans le présent chapitre, il faut entendre par centre commercial tout établissement comprenant un ensemble de magasins de vente, et éventuellement d'autres établissements recevant du public, qui sont, pour leurs accès et leur évacuation, tributaires de mails clos. […]",
