      citationCle: "§ 1. La réunion partielle du rez-de-chaussée avec deux autres niveaux par des trémies pour former le hall est admise dans les magasins de vente. § 1 bis. La réunion partielle du rez-de-chaussée avec quatre autres niveaux par des trémies pour former le hall est admise uniquement dans le mail des centres commerciaux. Dans ce cas : - la défense contre l'incendie est assurée par une installation d'extinction automatique à eau appropriée aux risques ; - le service de sécurité incendie est majoré d'un agent dès que le nombre de niveaux est supérieur à trois […]",
