      citationCle: "§ 1. Les exploitations, avec leurs annexes, situées à l'intérieur des centres commerciaux doivent être séparées entre elles par des parois en matériaux incombustibles, revêtements exclus. De plus et en aggravation de l'article CO 24 (§ 1), ces parois doivent être coupe-feu d'un degré égal au degré de stabilité au feu exigé pour la structure avec un minimum d'une demi-heure. § 2. Ces dispositions ne sont cependant pas exigées pour les exploitations des types M, N, T et W groupées sur une surface totale inférieure à 300 mètres carrés. § 3. […]",
