      versionEnVigueur: "1982-02-03",
      modifiePar: null,
      luLe: "2026-10-14",
      lecture: "api_legifrance",
      citationCle: "Les circulations principales, telles que définies à l'article CO 34 (§ 3), doivent être aménagées de telle sorte que le public puisse toujours joindre facilement deux sorties. Dans les étages et les sous-sols, ces circulations doivent desservir les escaliers visés à l'article M 12 ci-dessus. En outre, les escaliers ne débouchant pas directement sur l'extérieur doivent être reliés par des dégagements principaux aux deux sorties les plus proches. Si des circulations secondaires sont établies, elles doivent avoir une largeur minimale de 0,90 mètre. Elles doivent permettre la circulation facile du public entre les rayons de vente ou entre les lots de vitrines ou comptoirs qu'elles desservent. […]",
