      citationCle: "§ 1. Les locaux sont de la classe 3 pour la détermination du coefficient au sens de l'annexe de l'IT 246. § 2. Les mails sont désenfumés comme des locaux de superficie supérieure à 1 000 m², dans les conditions définies au § 7 de l'instruction technique 246. § 3. Les boutiques d'une superficie totale inférieure à 300 m², réserves d'approche comprises, et donnant sur un mail n'ont pas à être désenfumées. Leur superficie n'est pas prise en compte dans le calcul du désenfumage du mail. Un écran de cantonnement entre la boutique et le mail n'est pas imposé. § 4. Les commandes des dispositifs de désenfumage ne sont pas obligatoirement automatiques.",
