      motif: "Deux cahiers des charges que le PROPRIÉTAIRE ou le concessionnaire d'un hall d'expositions établit et annexe au registre de sécurité : avec l'organisateur de chaque manifestation (§ 1, validé par l'autorité administrative avec la demande d'autorisation de T 5 — une pièce de la manifestation, ligne de partage 1), et avec les locataires permanents (§ 2, « Ce cahier des charges doit être annexé au registre de sécurité »). Le second est une pièce permanente d'exploitant. Mais il ne vise que le propriétaire d'un lieu de foires et salons qui loue à des exploitants permanents : cas de niche pour la cible, ligne de partage 5 — annoncé, pas questionné. La salle d'exposition permanente de T 1 § 2 (concession automobile, bateaux) n'a ni organisateur ni locataire permanent au sens de ce chapitre.",
      declareA: DECLARE_A_CATEGORIE_ERP,
